package com.example

import com.example.ExamQuestionHelper.QSpec

internal object BuddhismG11LiveExamSuttaBank2 {
  private const val T = "සූත්‍ර ධර්ම හා පාලි ගාථා"

  private fun q(
    stem: String,
    c: String,
    d1: String,
    d2: String,
    d3: String,
    exp: String
  ) = QSpec(T, stem, c, listOf(d1, d2, d3), exp)

  fun questions(): List<QSpec> = listOf(
    q("'සංගාමේ මේ මතං සෙය්‍යෝ - යඤ්චේ ජීවේ පරාජිතෝ' යන ගාථාව ප්‍රකාශ කළ සූත්‍රය කුමක්ද?", "ධජග්ග සූත්‍රය", "ආටානාටිය සූත්‍රය", "මෝර පිරිත", "බොජ්ඣංග සූත්‍රය", "සිතේ ඇතිවන බිය තැතිගැන්ම දුරු කිරීමට තෙරුවන් ගුණ සිහි කරන ලෙස ධජග්ග සූත්‍රයේ දැක්වේ."),
    q("ධජග්ග සූත්‍රයේදී බියක් තැතිගැන්මක් ඇති වූ විට භික්ෂූන්ට සිහි කරන ලෙස බුදුරදුන් වදාළේ කුමක්ද?", "බුද්ධ, ධම්ම, සංඝ ගුණ", "ශක්‍ර දේවේන්ද්‍රයාගේ කොඩිය", "මහා බ්‍රහ්මයාගේ බලය", "සූර්ය දිව්‍යරාජයා", "වීතරාගී, වීතදෝසී, වීතමෝහී බුදුන් වහන්සේ ප්‍රමුඛ තෙරුවන් සිහි කිරීමෙන් බිය නැති වේ."),
    q("පංච ශීලය, සමාධිය හා මෛත්‍රිය රැකගෙන වනගතව වෙසෙද්දී සියලු සතුන්ගෙන් ආරක්ෂාව සැලසෙන පිරිත කුමක්ද?", "ඛන්ධ පිරිත", "වට්ටක පිරිත", "මෝර පිරිත", "අංගුලිමාල පිරිත", "අහි රාජ කුල සතරට මෙත් වැඩීමෙන් සර්ප දෂ්ටන ආදියෙන් ආරක්ෂා වන බව ඛන්ධ පිරිතේ එයි."),
    q("සත්‍ය බලයෙන් ගින්නෙන් ආරක්ෂා වූ කුරුළු පැටවෙකුගේ කතාව ඇතුළත් පිරිත් සූත්‍රය කුමක්ද?", "වට්ටක පිරිත", "ධජග්ග පිරිත", "මහාමංගල පිරිත", "රතන පිරිත", "මව්පියන්, තටු, පාද ක්‍රියාත්මක නොවන බව කියමින් සිදු කළ සත්‍ය ක්‍රියාව වට්ටක පිරිතයි."),
    q("සෑම දිනකම උදෑසන හා සවස බුදු ගුණ සිහි කර ආරක්ෂාව සලසා ගැනීම දැක්වෙන පිරිත කුමක්ද?", "මෝර පිරිත", "රතන පිරිත", "අංගුලිමාල පිරිත", "ගිරිමානන්ද සූත්‍රය", "රන්වන් මොණර බෝසතුන් උදේ සවස බුද්ධ නමස්කාරය කළ ආකාරය මෝර පිරිතේ එයි."),
    q("ගර්භණී මාතාවන්ට සුවපහසු දරු උපතක් ප්‍රාර්ථනා කරමින් දේශනා කරන පිරිත කුමක්ද?", "අංගුලිමාල පිරිත", "ඛන්ධ පිරිත", "මෝර පිරිත", "වට්ටක පිරිත", "ආර්ය ජාතියේ උපන් තැන් පටන් දැන දැන සතෙකු නොමැරූ බවට කළ සත්‍ය ක්‍රියාවයි."),
    q("ගිලන් වූ භික්ෂුවකට දස සංඥා විස්තර කර රෝග පීඩාවන් සංසිඳවීමට දෙසූ සූත්‍රය කුමක්ද?", "ගිරිමානන්ද සූත්‍රය", "රතන සූත්‍රය", "සතිපට්ඨාන සූත්‍රය", "ආලවක සූත්‍රය", "අනිච්ච, අනත්ත, අසුභ ආදී දස සංඥා මෙනෙහි කිරීමෙන් ගිරිමානන්ද හිමි සුවපත් වූහ."),
    q("පාලි ගාථා අතර 'බුද්ධෝ භවේ සම්පරායේ' හා සම්බන්ධ 'මහාවග්ග' ග්‍රන්ථය අයත් වන්නේ කුමන පිටකයටද?", "විනය පිටකයට", "සූත්‍ර පිටකයට", "අභිධර්ම පිටකයට", "වංශකතාවලට", "මහාවග්ග හා චුල්ලවග්ග පාලි ග්‍රන්ථ විනය පිටකයේ කොටස් වේ."),
    q("'ඉතිපි සෝ භගවා අරහං සම්මාසම්බුද්ධෝ...' යන බුදු ගුණ නවය අතර 'විජ්ජාචරණ සම්පන්නෝ' යන්නෙහි අර්ථය කුමක්ද?", "විද්‍යාවෙන් හා චරණ ධර්මවලින් සමන්විත වූ", "ලෝකය මැනවින් දන්නා වූ", "දෙව් මිනිසුන්ට ශාස්තෘ වූ", "මනා ගමන් ඇති", "ත්‍රිවිද්‍යා අෂ්ට විද්‍යා හා පසළොස් චරණ ධර්මයන්ගෙන් යුක්ත බව විජ්ජාචරණ සම්පන්න ගුණයයි."),
    q("බුදු ගුණ නවයෙන් 'සුගතෝ' යන ගුණයෙන් ප්‍රකාශ වන අර්ථය කුමක්ද?", "සුන්දර නිවන් මඟට මනාව ගමන් කළ හා සත්‍ය වචන වදාරන", "නැවත නූපදින බව", "සියලු දුක් දන්නා බව", "සංඝයා පාලනය කරන බව", "යහපත් ගමන් ඇති හෙයින් හා සුන්දර නිවනට වැඩි හෙයින් සුගත නම් වේ."),
    q("බුදු ගුණ අතර 'අනුත්තරෝ පුරිසදම්ම සාරථී' යන්නෙන් අදහස් වන්නේ කුමක්ද?", "දමනය කළ යුතු පුද්ගලයන් දමනය කිරීමේහි අසහාය රියදුරාණන් බව", "සියලු ලෝක ධාතු දන්නා බව", "අන් අයගෙන් පිදුම් ලැබීමට සුදුසු බව", "සත්‍යය අවබෝධ කළ බව", "අංගුලිමාල, ආලවක ආදීන් දමනය කළ බැවින් අනුත්තර පුරිසදම්ම සාරථී නම් වේ."),
    q("බුදුරදුන් 'සත්ථා දේවමනුස්සානං' යනුවෙන් හැඳින්වෙන්නේ කුමන කරුණක් නිසාද?", "දෙවියන්ට හා මිනිසුන්ට සසරින් එතෙර වීමට අනුශාසනා කරන ශාස්තෘවරයා වන බැවින්", "මිනිසුන්ට පමණක් දෙසන බැවින්", "තපස් රකින බැවින්", "රාජ්‍ය පාලනය කරන බැවින්", "දෙව් මිනිස් සැමට යහමග පෙන්වන ගුරුවරයාණන් බැවිනි."),
    q("ධර්ම ගුණ හයෙන් 'ස්වාක්ඛාතෝ' යන පදයෙන් පැහැදිලි වන්නේ කුමක්ද?", "මුල, මැද, අග යහපත් ලෙස මනාව දේශනා කරන ලද බව", "කල් නොයවා ප්‍රතිඵල දෙන බව", "ඇවිත් බලන්නැයි ආරාධනා කළ හැකි බව", "නුවණැත්තන් තමා තුළින්ම දැකිය යුතු බව", "ආදි කල්‍යාණ, මජ්ඣේ කල්‍යාණ, පරියෝසාන කල්‍යාණ ලෙස ධර්මය මනාව දෙසා ඇත."),
    q("ධර්ම ගුණ අතර 'අකාලිකෝ' යන්නෙහි සැබෑ අර්ථය කුමක්ද?", "කල් නොයවා එසැණින්ම විපාක ලබා දෙන බව", "කාලයකට පමණක් සීමා වූ බව", "සියවසකට පසු පල දෙන බව", "අතීතයට පමණක් අදාළ බව", "ආර්ය මාර්ගය වැඩූ සැණින් ඵලය උපදවන බැවින් කල් නොයවා පල දෙයි."),
    q("'ඒහිපස්සිකෝ' යන ධර්ම ගුණයෙන් ප්‍රකාශ වන්නේ කුමක්ද?", "පැමිණ පරීක්ෂා කර බලන්න යැයි විවෘතව ආරාධනා කළ හැකි බව", "රහසිගතව තබාගත යුතු බව", "අන්ධයන් ලෙස පිළිගත යුතු බව", "පැරණි චාරිත්‍ර පමණක් රැකිය යුතු බව", "සත්‍ය ධර්මය නිර්භීතව විමර්ශනයට විවෘතය."),
    q("'පච්චත්තං වේදිතබ්බෝ විඤ්ඤූහි' යන ධර්ම ගුණයේ අර්ථය කුමක්ද?", "නුවණැත්තන් විසින් තම තමන්ගේ සිතින්ම ප්‍රත්‍යක්ෂ කරගත යුතු බව", "අන් අය ලවා අවබෝධ කරගත යුතු බව", "මුදල් දී ලබාගත යුතු බව", "පොත්වලින් පමණක් කියවිය යුතු බව", "විමුක්ති සුවය පුද්ගලිකවම අත්විඳිය යුතු ධර්මයකි."),
    q("සංඝ ගුණ නවය අතර 'සුපටිපන්නෝ' යන්නෙන් අදහස් වන්නේ කුමක්ද?", "ආර්ය අෂ්ටාංගික මාර්ගයේ මනාව පිළිපන් බව", "ඍජු මාර්ගයේ ගමන් කරන බව", "නිවන් මඟට යොමුව ගමන් කරන බව", "සුදුසු සේ පිළිපන් බව", "බුදුරදුන් දෙසූ ශික්ෂා පදවල මැනවින් පිහිටා කටයුතු කිරීම සුපටිපන්න ගුණයයි."),
    q("සංඝ ගුණ අතර 'උජුපටිපන්නෝ' යන්නෙහි අර්ථය කුමක්ද?", "වංක නොවී ඍජු මාර්ගයේ පිළිපන් බව", "දුර ගමන් කරන බව", "උස් ස්ථානවල වෙසෙන බව", "මධ්‍යස්ථව නොසිටින බව", "කාය වංක ආදියෙන් තොරව මධ්‍යම ප්‍රතිපදාවේ ඍජුව ගමන් කිරීමයි."),
    q("සංඝ ගුණ අතර 'අනුත්තරං පුඤ්ඤක්ඛෙත්තං ලෝකස්ස' යන්නෙන් දැක්වෙන්නේ කුමක්ද?", "ලෝකයාට පින් රැස් කර ගැනීමට ඇති අති උතුම් කෙත බව", "දුර සිට ගෙනැවිත් පිදිය යුතු බව", "ආගන්තුකයන්ට පිදිය යුතු බව", "ඇඳිලි බැඳ නමස්කාර කළ යුතු බව", "සරු කෙතක බීජ වැපිරූ විට මහා අස්වනු ලැබෙන්නා සේ සඟරුවනට දුන් දානය මහත්ඵල වේ."),
    q("ධම්මපදයේ 'අප්පමාද වග්ගයේ' දැක්වෙන පරිදි බුදුවරුන්ට පවා ප්‍රිය වූ ධර්මය කුමක්ද?", "අප්‍රමාදය", "ධනය", "කීර්තිය", "උදාසීනත්වය", "අප්‍රමාදව කුසල් වැඩීම සියලු සම්පත්තියට හේතු වේ."),
    q("ධම්මපදයේ 'පණ්ඩිත වග්ගයට' අනුව පණ්ඩිතයා නින්දා ප්‍රශංසා හමුවේ ක්‍රියා කරන්නේ කුමන උපමාව අනුවද?", "ඒකඝන ගල් පර්වතයක් මෙන්", "කෙසෙල් කඳක් මෙන්", "සුළඟින් සැලෙන කොළයක් මෙන්", "දිය බුබුළක් මෙන්", "'සේලෝ යථා ඒකඝනෝ වාතේන න සමීරති' ලෙස නුවණැත්තෝ නොසැලෙති."),
    q("ධම්මපදයේ 'අත්ත වග්ගයට' අනුව 'අත්තනාව කතං පාපං' යන්නෙහි තේරුම කුමක්ද?", "තමා විසින් කළ පාපය තමාම කෙලෙසන බව", "අන් අය කළ පවින් තමා දුක් විඳින බව", "පාපය අන් අයට බැර කළ හැකි බව", "පව් කිරීමෙන් ශුද්ධ වන බව", "තමා විසින්ම සිත කිලිටි කරගන්නා බවත් තමාම පිරිසිදු විය යුතු බවත් දැක්වේ."),
    q("ධම්මපදයේ 'සුඛ වග්ගයේ' එන 'නිබ්බාණං පරමං සුඛං' යන්නට අනුව පරම සුවය කුමක්ද?", "නිවන", "මිහිරි ආහාර", "රජ සැප", "පිරිවර සැප", "තෘෂ්ණාව නැති කළ නිවන සියලු සැපයන් අතර ශ්‍රේෂ්ඨම සුවයයි."),
    q("ධම්මපදයේ 'දණ්ඩ වග්ගයේ' එන 'සබ්බේ තසන්ති දණ්ඩස්ස' ගාථාවෙන් උගන්වන සදාචාර පාඩම කුමක්ද?", "සියලු සතුන් දඬුවමට හා මරණයට බිය හෙයින් හිංසා නොකළ යුතු බව", "බලවතුන් දුබලයන්ට දඬුවම් කළ යුතු බව", "තිරිසන් සතුන්ට මරණ බිය නැති බව", "දඬුවම් දීම සතුටක් බව", "තමා උපමා කරගෙන අන් සතුන් නොනැසිය යුතු බව මෙයින් කියවේ."),
    q("ධම්මපදයේ 'කෝධ වග්ගයේ' එන 'අක්කෝධේන ජිනේ කෝධං' ගාථාවට අනුව මසුරු මිනිසා දිනිය යුත්තේ කුමකින්ද?", "දන් දීමෙන් (දානේන කදරියං)", "සත්‍යයෙන්", "කෝපයෙන්", "බලයෙන්", "අසාධු සාධුනා ජිනේ, ජිනේ කදරියං දානේන යනුවෙන් දැක්වේ."),
    q("ධම්මපදයේ 'තණ්හා වග්ගයේ' එන 'සබ්බදානං ධම්මදානං ජිනාති' යන්නෙන් ශ්‍රේෂ්ඨම දානය ලෙස දක්වන්නේ කුමක්ද?", "ධර්ම දානය", "ආහාර දානය", "වස්ත්‍ර දානය", "විහාර දානය", "සියලු රසයන් ධර්ම රසයෙන්ද, සියලු ඇලීම් ධර්ම රතියෙන්ද දිනයි."),
    q("ධම්මපදයේ 'බාල වග්ගයට' අනුව බාලයෙකු (අඥානයෙකු) තමා බාලයෙකු බව දැනගන්නේ නම් කුමක් වේද?", "පණ්ඩිතයෙකු වැනි වේ", "තවත් අඥාන වේ", "විනාශයට පත් වේ", "ප්‍රතික්ෂේප වේ", "තමාගේ නොදැනුවත්කම වටහා ගැනීම නිවැරදි වීමේ ආරම්භයයි."),
    q("ධම්මපදයේ 'මග්ග වග්ගයේ' 'තුම්හේහි කිච්චං ආතප්පං - අක්ඛාතාරෝ තථාගතා' යන්නෙහි අර්ථය කුමක්ද?", "වීර්යය වැඩීම ඔබ විසින් කළ යුතු අතර බුදුවරු මඟ කියා දෙන්නෝය", "බුදුවරු අන් අය නිවනට ඔසවා තබති", "උත්සාහයකින් තොරව නිවන් දැකිය හැක", "ප්‍රාතිහාර්යයෙන් නිවන් ලැබේ", "බුදුරදුන් මාර්ගෝපදේශකයෙකු මිස ගැලවුම්කරුවෙකු නොවන බව පැහැදිලි වේ."),
    q("ධම්මපදයේ 'පුප්ඵ වග්ගයේ' 'යථාපි භමරෝ පුප්ඵං' ගාථාවෙන් භික්ෂුවකගේ පිණ්ඩපාත ගමන උපමා කර ඇත්තේ කුමකටද?", "මල නොතළා රොන් ගන්නා බඹරෙකුට", "වැවට බසින ඇතෙකුට", "ගොදුරු සොයන සිංහයෙකුට", "වලාකුළකට", "දායකයන්ගේ ශ්‍රද්ධාව හා ආර්ථිකය නොතළා සිඟා වැඩිය යුතු බව දැක්වේ."),
    q("ධම්මපදයේ 'සහස්ස වග්ගයේ' සඳහන් පරිදි යුද්ධයෙන් දහස් ගණනක් පරදවන්නාට වඩා ශ්‍රේෂ්ඨ වන්නේ කවුද?", "තමන්ගේ සිත දිනා ගන්නා තැනැත්තා", "රාජ්‍ය පාලකයා", "විශාල හමුදාවක් ඇත්තා", "ධනවත් වෙළෙන්දා", "'සංගාමේ ජිනේ' යන්නට වඩා 'අත්තානමේව ජෙය්‍ය' හෙවත් සිත ජය ගැනීම උතුම්ය."),
    q("සිඟාලෝවාද සූත්‍රයේ මිතුරන් පරීක්ෂා කිරීමට සමාන කර ඇති 'පානභූමික' හෙවත් අපායසහාය මිත්‍රයා යනු කවුද?", "සුරාව, සූදුව වැනි පාප ක්‍රියාවන්ට සහාය වන්නා", "දුකේදී පිහිට වන්නා", "ධනය පරිත්‍යාග කරන්නා", "නිවන් මග කියා දෙන්නා", "අපායට හා විනාශයට මඟ පෙන්වන බොරු මිතුරා අපායසහාය වේ."),
    q("වසල සූත්‍රයේදී 'පරදාර සේවනය' හඳුන්වා ඇත්තේ කුමන ආකාරයෙන්ද?", "වසල ක්‍රියාවක් ලෙස", "රාජ ධර්මයක් ලෙස", "මංගල කරුණක් ලෙස", "සුගති මඟක් ලෙස", "ඥාතීන්ගේ හා මිතුරන්ගේ බිරින්දෑවරුන් ඉක්මවා යෑම වසල ලක්ෂණයකි."),
    q("පරාභව සූත්‍රයේදී 'නිද්දාසීලී සභාසීලී' යන්නෙන් දැක්වෙන පිරිහීමේ ලක්ෂණ මොනවාද?", "නිද්‍රාශීලී බව, සමාජ ශාලාවල කාලය නාස්ති කිරීම, අලස බව", "ධර්ම සාකච්ඡාවල යෙදීම", "උදෑසන අවදි වීම", "දන් පැන් පිදීම", "කම්මැලිකම හා කේන්ති ගැනීම පුද්ගල පිරිහීමට හේතු වේ."),
    q("රතන සූත්‍රයේ 'යං කිඤ්චි විත්තං ඉධ වා හුරං වා' යන්නෙන් අදහස් වන්නේ කුමක්ද?", "මෙලොව පරලොව ඇති කවර ධනයකටත් වඩා තථාගත රත්නය උතුම් බව", "රන් රිදී ධනය උතුම් බව", "දිව්‍ය සම්පත් ශ්‍රේෂ්ඨ බව", "රාජ්‍ය බලය සියල්ලට ඉහළ බව", "තෙරුවන් හා සම කළ හැකි වස්තුවක් තුන්ලොවම නොමැති බව දැක්වේ."),
    q("කරණීයමෙත්ත සූත්‍රයේ 'න පරෝ පරං නිකුබ්බේථ' යන්නෙන් උපදෙස් දෙන්නේ කුමක් ගැනද?", "කිසිවෙකු කිසිවෙකු නොරවටන ලෙස", "කිසිවෙකු සමඟ කතා නොකරන ලෙස", "සියල්ල අත්හැර යන ලෙස", "තරහ ගන්නා ලෙස", "අනෙකා රැවටීම හෝ හෙළා දැකීම නොකළ යුතු බව මෛත්‍රී සූත්‍රයේ දැක්වේ."),
    q("ධම්මචක්කප්පවත්තන සූත්‍රයට අනුව බුදුරදුන් ප්‍රථමයෙන්ම අවබෝධ කළ ඥාන දර්ශනය දේශනා කරද්දී කම්පා වූයේ කුමක්ද?", "දස දහසක් සක්වළ ලෝක ධාතුව", "ජේතවනාරාමය පමණි", "රජගහ නුවර පමණි", "හිමාල පර්වතය පමණි", "ධර්ම චක්‍රය පැවැත්වූ කල්හි දෙව් බඹුන් සාධුකාර දුන් බව දැක්වේ."),
    q("සූත්‍ර පිටකයේ සංයුත්ත නිකායේ දැක්වෙන 'දාරුක්ඛන්ධූපම සූත්‍රයේ' ගඟේ පාවෙන දර කොටය සාගරයට යෑමට ඉවත් කළ යුතු බාධක ගණන කීයද?", "අටකි", "හතරකි", "පහකි", "දසයකි", "මෙතෙරට නොපැමිණීම, එතෙරට නොපැමිණීම ආදී අන්තරාය අට දුරු කිරීමෙන් නිවන් සාගරයට පැමිණේ."),
    q("කසීභාරද්වාජ සූත්‍රයේදී බුදුරදුන් 'මගේ ගොවිතැනේ ඵලය කුමක්දැ'යි පැවසුවේ කුමක් ලෙසද?", "අමෘතය (නිවන)", "රන් කහවණු", "ධාන්‍ය අස්වැන්න", "රාජ්‍යය", "ශ්‍රද්ධාව බීජය වී වීර්යය ගවයන් වී සිදු කරන ආධ්‍යාත්මික ගොවිතැනේ ඵලය නිවනයි."),
    q("සෝණදණ්ඩ සූත්‍රයේ සඳහන් 'සීලපරිධෝතා හි පඤ්ඤා පඤ්ඤාපරිධෝතං සීලං' යන්නෙහි අර්ථය කුමක්ද?", "සීලයෙන් ප්‍රඥාවත් ප්‍රඥාවෙන් සීලයත් පිරිසිදු වන බව", "සීලය ප්‍රඥාවට බාධාවක් බව", "ප්‍රඥාව පමණක් ප්‍රමාණවත් බව", "සීලයට වඩා ධනය උසස් බව", "දෙඅතක් එකිනෙක සෝදන්නා සේ සීලය හා ප්‍රඥාව ඔවුනොවුන් පෝෂණය කරයි."),
    q("බුදුරදුන් විසින් 'බහුජන හිතාය බහුජන සුඛාය' යනුවෙන් දේශනා කළේ කුමන අවස්ථාවකදීද?", "ප්‍රථම ධර්මදූත පිරිස පිටත් කරන විට", "අවසන් බුද්ධ වචනයේදී", "කපිලවස්තුවට වඩිද්දී", "සංගායනාවකදී", "බොහෝ දෙනාගේ හිතසුව පිණිස ලෝකානුකම්පාවෙන් ධර්ම චාරිකාවේ වඩින ලෙස වදාළහ."),
    q("පාලි ත්‍රිපිටකයේ සඳහන් 'වම්මික සූත්‍රයේ' දිවා රෑ දෙකේ දුම් දමමින් ගිනි ගන්නා තුඹස උපමා කර ඇත්තේ කුමකටද?", "මිනිස් ශරීරයට", "වනාන්තරයට", "රාජ මාලිගයට", "මහා සාගරයට", "කුමාර කාශ්‍යප හිමිට දෙසූ වම්මික සූත්‍රයේ තුඹස යනු ශරීරයයි."),
    q("මධුපිණ්ඩික සූත්‍රයේදී මනසේ ඇතිවන අකුසල චින්තන ප්‍රපංච නැති කර ගැනීමට මඟ පෙන්වූයේ කවුද?", "බුදුරදුන් හා මහා කච්චායන හිමි", "ආනන්ද හිමි", "රාහුල හිමි", "උපාලි හිමි", "දණ්ඩපාණී ශාක්‍යයාගේ ප්‍රශ්නයට බුදුරදුන් කෙටියෙන් දෙසූ දහම කච්චායන හිමි විස්තර කළහ."),
    q("චක්කවත්ති සීහනාද සූත්‍රයට අනුව සමාජයේ සදාචාර පිරිහීමෙන් අවසානයේ පහළ වන විනාශකාරී කාලය කුමක්ද?", "සත්ථන්තර කල්පය", "දුර්භික්ෂ කල්පය", "සුභික්ෂ කාලය", "රෝග කල්පය", "අවි ආයුධ ගෙන එකිනෙකා නසාගන්නා සත්ථන්තර කල්පයෙන් පසු මෛත්‍රියෙන් යළි සමාජය ගොඩනැගේ."),
    q("බුදුරදුන් දෙසූ 'පුග්ගල සූත්‍රයක' මිනිසුන් සතර දෙනෙකු අඳුර හා ආලෝකය අනුව වර්ග කෙරේ. ඉන් ශ්‍රේෂ්ඨතම තැනැත්තා කවුද?", "ආලෝකයේ සිට ආලෝකයට යන්නා (ජෝතිජෝතිපරායණ)", "අඳුරේ සිට අඳුරට යන්නා", "ආලෝකයේ සිට අඳුරට යන්නා", "නිහඬව සිටින්නා", "යහපත් උපතක් ලබා කුසල් වැඩීමෙන් උසස් ගමනක් යන්නා ජෝතිජෝතිපරායණ නම් වේ."),
    q("සිඟාලෝවාද සූත්‍රය අනුව මව්පියන් විසින් දරුවන්ට ඉටු කළ යුතු යුතුකම් පහ අතර පළමු යුතුකම කුමක්ද?", "පාපයෙන් වැළැක්වීම", "විවාහ කර දීම", "ධනය පැවරීම", "ශිල්ප ඉගැන්වීම", "පවින් වළක්වා යහපතෙහි යෙදවීම මව්පියන්ගේ මූලික වගකීමයි."),
    q("සිඟාලෝවාද සූත්‍රයට අනුව දරුවන් මව්පියන්ට ඉටු කළ යුතු යුතුකම් පහ අතරට අයත් වන්නේ කුමක්ද?", "වයස්ගත මව්පියන් පෝෂණය කිරීම (භතෝ නේසං භරිස්සාමි)", "මව්පියන්ගෙන් වෙන්වීම", "උපදෙස් නොසලකා හැරීම", "කුල පරපුර විනාශ කිරීම", "පෝෂණය, කටයුතු කරදීම, කුල පරපුර රැකීම, දායාද සුදුසු වීම, පින් දීම යුතුකම් පහයි."),
    q("සිඟාලෝවාද සූත්‍රයේදී ශිෂ්‍යයා ගුරුවරයාට ඉටු කළ යුතු යුතුකම් පහෙන් එකක් වන්නේ කුමක්ද?", "උත්ථානයෙන් (නැගිට ගෞරව දැක්වීමෙන්) පිළිගැනීම", "ගුරුවරයා විවේචනය කිරීම", "පාඩම් අතපසු කිරීම", "නිහඬව ඉවතට යෑම", "උත්ථාන, උපට්ඨාන, සුස්සූසා, පාරිචරියා, සක්කච්චං සිප්පපටිග්ගහණ යුතුකම් පහයි."),
    q("සිඟාලෝවාද සූත්‍රයට අනුව ස්වාමියා විසින් බිරිඳට ඉටු කළ යුතු යුතුකම් පහට අයත් වන්නේ කුමක්ද?", "සම්මානනා (ගෞරවයෙන් සැලකීම)", "අවමන් කිරීම", "ආභරණ නොදීම", "වගකීම් පැවරීම වැළැක්වීම", "ගෞරවය, අවමන් නොකිරීම, අනාචාරයේ නොහැසිරීම, නිවසේ අධිපති බව දීම, වස්ත්‍රාභරණ දීම."),
    q("සිඟාලෝවාද සූත්‍රයට අනුව ස්වාමියා සේවකයන්ට ඉටු කළ යුතු යුතුකමක් නොවන්නේ කුමක්ද?", "ශක්තිය ඉක්මවා බර වැඩ පැවරීම", "නිසි කලට වැටුප් හා ආහාර දීම", "රෝගී වූ විට උපස්ථාන කිරීම", "නිවාඩු හා විවේකය ලබා දීම", "ශක්ති පමණින් වැඩ පැවරීම (යථා බලං කම්මන්ත සංවිධානේන) බුදුදහමේ කම්කරු අයිතියයි."),
    q("බුදුරදුන් දෙසූ 'සත්තභරියා සූත්‍රය' දේශනා කළේ කවර කාන්තාවකගේ නිවසේදීද?", "සුජාතා නම් අනේපිඬු සිටු ලේලිය අරභයා", "විශාඛා දේවියට", "මල්ලිකා දේවියට", "ඛේමා දේවියට", "වධක සමා ආදී භාර්යාවන් හත්දෙනා ගැන දෙසා සුජාතාව දමනය කළහ."),
    q("සත්තභරියා සූත්‍රයේ ඉගැන්වෙන ප්‍රශංසනීය භාර්යාවන් අතර ස්වාමියාට සැබෑ මිතුරියක සේ සිටින භාර්යාව කවුද?", "සඛී භරියාව", "වධක භරියාව", "චෝරී භරියාව", "අය්‍යා භරියාව", "මාතු, භගිනි, සඛී, දාසි යන භාර්යාවෝ සතරදෙනා සුගතිගාමී යහපත් භාර්යාවෝ වෙති."),
    q("මහා කාශ්‍යප හිමියන් රෝගී වූ විට බුදුරදුන් ගොස් දේශනා කළේ කවර සූත්‍රයද?", "බොජ්ඣංග සූත්‍රය", "මංගල සූත්‍රය", "කරණීයමෙත්ත සූත්‍රය", "සිඟාලෝවාද සූත්‍රය", "සප්ත බොජ්ඣංග ධර්ම සිහි කිරීමෙන් මහා කාශ්‍යප හිමි සුවපත් වූහ."),
    q("දෙව්දත් හිමිගේ පිරිසට එක්ව සිටි රජුන්ට බුදුරදුන් දෙසූ 'සම්පසාදනීය සූත්‍රය' දේශනා කළේ කවුරුන් විසින්ද?", "සැරියුත් හිමියන් විසින්", "ආනන්ද හිමියන් විසින්", "මුගලන් හිමියන් විසින්", "උපාලි හිමියන් විසින්", "සැරියුත් හිමියන් බුදුරදුන් කෙරෙහි ඇති අසීමිත ශ්‍රද්ධාව සිංහනාදයක් ලෙස ප්‍රකාශ කළහ."),
    q("දීඝ නිකායේ 'ලක්ඛණ සූත්‍රයෙන්' ප්‍රධාන වශයෙන් විස්තර කෙරෙන්නේ කුමක්ද?", "බුදුරදුන්ගේ දෙතිස් මහා පුරුෂ ලක්ෂණ හා ඊට හේතු වූ පෙර කුසල්", "රාජ්‍ය පාලන ක්‍රම", "අභිධර්ම විග්‍රහය", "විනය නීති", "පෙර භවවල කළ උදාර කුසල කර්ම හේතුවෙන් මහා පුරුෂ ලක්ෂණ පහළ වූ අයුරු දැක්වේ."),
    q("ධම්මපදයේ 'පිය වග්ගයේ' එන 'පියතෝ ජායතී සෝකෝ' යන්නෙහි අර්ථය කුමක්ද?", "ප්‍රියයන්ගෙන් හා ඇලීමෙන් ශෝකය හා බිය හටගන්නා බව", "ප්‍රියයන් නිසා බිය නැති වන බව", "ධනයෙන් ශෝකය නැති වන බව", "ඇලීමෙන් නිවන් ලැබෙන බව", "ප්‍රිය විප්‍රයෝගය නිසා සිතේ දුක හා බිය උපදින බව දැක්වේ."),
    q("'සුඛා සංඝස්ස සාමග්ගී' යන ධම්මපද ගාථාවෙන් අවධාරණය කරන්නේ කුමක්ද?", "සංඝයාගේ හෙවත් සමූහයේ සමගිය සැපයක් බව", "වෙන් වී සිටීම සැපයක් බව", "තර්ක කිරීම උතුම් බව", "බලය ප්‍රධාන බව", "එකමුතුකම හා සමගිය සමාජ සුබසිද්ධියට හේතු වේ."),
    q("ධම්මපදයේ 'මල වග්ගයේ' දැක්වෙන පරිදි යකඩයෙන් උපන් මලකඩ එම යකඩයම කා දමන්නා සේ පුද්ගලයා නසන්නේ කුමක්ද?", "තමා විසින්ම කරන ලද අකුසල කර්ම", "වෙනත් අයගේ වචන", "කාලගුණික විපර්යාස", "දුර බැහැර ගමන්", "'අයසාව මලං සමුට්ඨිතං' උපමාවෙන් අකුසලයේ ආදීනව පෙන්වයි."),
    q("සූත්‍ර පිටකයේ අංගුත්තර නිකාය සකස් වී ඇති ක්‍රමවේදය කුමක්ද?", "එකේ සිට එකොළහ දක්වා සංඛ්‍යාත්මක නිපාත ක්‍රමයට", "දීර්ඝත්වය අනුව", "ගාථා ප්‍රමාණය අනුව", "කතුවරුන් අනුව", "ඒකක නිපාතයේ සිට ඒකාදසක නිපාතය දක්වා නිපාත 11 කින් යුක්තය."),
    q("සූත්‍ර පිටකයේ සංයුත්ත නිකාය සකස් වී ඇති ආකාරය කුමක්ද?", "විෂය කරුණු අනුව කොටස් (සංයුත්ත) 56 කට බෙදා", "අකාරාදී පිළිවෙළට", "දිග සූත්‍ර අනුව", "පුද්ගල නාම අනුව", "සගාථ, නිදාන, ඛන්ධ, සළායතන, මහා වශයෙන් වග්ග පහකට බෙදා ඇත."),
    q("මජ්ඣිම නිකාය කොටස් තුනකට බෙදා ඇත. එහි පළමු පණ්ණාසකය කුමක්ද?", "මූලපණ්ණාසකය", "මජ්ඣිමපණ්ණාසකය", "උපරිපණ්ණාසකය", "මහාවග්ගය", "මූල, මජ්ඣිම, උපරි පණ්ණාසක තුනේ මුළු සූත්‍ර 152 ක් අඩංගු වේ."),
    q("බුදුරදුන් සමයේ විසූ භික්ෂූන් වහන්සේලාගේ උදාන ගාථා සංග්‍රහ කර ඇති ඛුද්දක නිකායේ ග්‍රන්ථය කුමක්ද?", "ථේරගාථා", "ථේරීගාථා", "විමානවත්ථු", "පේතවත්ථු", "මහරහතන් වහන්සේලා විමුක්ති සුවය ප්‍රකාශ කළ ගාථා ථේරගාථාවල අඩංගුය."),
    q("මහරහත් තෙරණියන් වහන්සේලාගේ ජීවන අත්දැකීම් හා නිවන් සුව ප්‍රකාශිත ග්‍රන්ථය කුමක්ද?", "ථේරීගාථා", "ථේරගාථා", "බුද්ධවංසය", "චරියාපිටකය", "ඛේමා, පටාචාරා, අම්බපාලි ආදී තෙරණියන්ගේ ගාථා මෙහි අඩංගු වේ."),
    q("සුත්ත නිපාතයේ 'උරග වග්ගයේ' ඇතුළත් ඉතා ජනප්‍රිය සූත්‍ර දෙකක් මොනවාද?", "කරණීයමෙත්ත හා වසල සූත්‍ර", "මහාපරිනිබ්බාන හා බ්‍රහ්මජාල", "සිඟාලෝවාද හා අග්ගඤ්ඤ", "ධම්මචක්ක හා අනත්තලක්ඛණ", "පරාභව, කසීභාරද්වාජ හා රතන සූත්‍ර ද සුත්ත නිපාතයේ අඩංගුය."),
    q("ගිහි ජීවිතයේදී මුහුණ දෙන අටලෝ දහම විස්තර වන 'ලෝකධම්ම සූත්‍රය' අයත් නිකාය කුමක්ද?", "අංගුත්තර නිකාය (අට්ඨක නිපාතය)", "දීඝ නිකාය", "මජ්ඣිම නිකාය", "සංයුත්ත නිකාය", "ලාභ-අලාභ, යස-අයස, නින්දා-ප්‍රශංසා, සුඛ-දුක්ඛ අටලෝ දහම එහි විස්තර වේ."),
    q("නිවන් මඟෙහිදී අප අනුගමනය කළ යුතු කල්‍යාණ මිත්‍රත්වයේ පූර්ණ බව බුදුරදුන් වදාළේ කුමන සූත්‍රයේද?", "උපඩ්ඪ සූත්‍රයේ", "ආලවක සූත්‍රයේ", "මෝර පිරිතේ", "රතන සූත්‍රයේ", "කල්‍යාණ මිත්‍ර ඇසුර ශාසන බ්‍රහ්මචර්යාවෙන් අඩක් නොව සම්පූර්ණ බ්‍රහ්මචර්යාව බව ආනන්ද හිමිට වදාළහ."),
    q("ආනන්ද හිමියන් 'පින්වත් භික්ෂූන්ට කල්‍යාණ මිත්‍රත්වය නිවන් මඟෙන් අඩක්' යැයි පැවසූ විට බුදුරදුන් කුමක් වදාළේද?", "එසේ නොකියන්න, එය මුළු මහත් නිවන් මඟම වේ", "එය ඉතා කුඩා කොටසකි", "කල්‍යාණ මිත්‍රයන් අවශ්‍ය නොවේ", "එය ගිහියන්ට පමණක් අදාළය", "මුළුමනින්ම නිවන් මඟ සපිරෙන්නේ කල්‍යාණ මිත්‍ර සේවනයෙන් බව වදාළහ."),
    q("පාලි ගාථා අතර 'සබ්බේ සත්තා ආහාරට්ඨිතිකා' යනුවෙන් දක්වන පළමු ආහාරය කුමක්ද?", "කබලිංකාර ආහාරය (ඝන හා දියර ආහාර)", "ඵස්ස ආහාරය", "මනෝසඤ්චේතනා ආහාරය", "විඤ්ඤාණ ආහාරය", "සියලු සත්වයෝ ආහාර සතර මත යැපෙන බව සංගීති සූත්‍රයේ දැක්වේ."),
    q("බුදුරදුන් විසින් 'බ්‍රාහ්මණ වග්ගයේ' දී නියම බ්‍රාහ්මණයා ලෙස හඳුන්වන්නේ කවුරුන්ද?", "සියලු කෙලෙසුන් නැසූ මහරහතන් වහන්සේ", "වේද හදාරන බමුණා", "යාග හෝම කරන්නා", "කුලයෙන් උසස් තැනැත්තා", "රාග, ද්වේෂ, මෝහ ක්ෂය කළ උතුමා සැබෑ බ්‍රාහ්මණයා බව ධම්මපදයේ එයි."),
    q("අනුන්ගේ යහපත පිණිස කතා කරන 'පියවාචා' ගුණය දැක්වෙන සුභාෂිත සූත්‍රයේ කතා කිරීමට සුදුසු වචන අංග ගණන කීයද?", "හතරකි (සුභාෂිත ලක්ෂණ)", "දෙකකි", "හයකි", "අටකි", "සුභාෂිත, ධම්ම, පියවාචා, සච්ච වශයෙන් වචනයේ අංග හතරක් සුභාෂිත සූත්‍රයේ වේ."),
    q("සුභාෂිත සූත්‍රයට අනුව කතා කළ යුතු වචනයක් සතු විය යුතු ලක්ෂණ අතරට අයත් නොවන්නේ කුමක්ද?", "කේළාම් හා පරුෂ වචන වීම", "සුභාෂිත වීම", "ධර්මානුකූල වීම", "සත්‍ය හා ප්‍රිය වචන වීම", "යහපත්, දැහැමි, ප්‍රියමනාප හා සත්‍ය වචන පමණක් පැවසිය යුතුය."),
    q("මිතුරෙකු හා සතුරෙකු හඳුනා ගන්නා ආකාරය දැක්වෙන 'සත්තජටිල සූත්‍රයේ' පුද්ගලයෙකුගේ සීලය දැනගත හැක්කේ කුමකින්ද?", "දිගු කලක් එකට වාසය කිරීමෙන්", "බාහිර පෙනුමෙන්", "පවසන වචනවලින් පමණක්", "වස්ත්‍ර පැළඳුම්වලින්", "සංවාසේන භික්ඛවේ සීලං වේදිතබ්බං යනුවෙන් කල් යෑමේදී සීලය හඳුනා ගත හැකි බව වදාළහ."),
    q("සත්තජටිල සූත්‍රයට අනුව පුද්ගලයෙකුගේ ප්‍රඥාව දැනගත හැක්කේ කුමකින්ද?", "ධර්ම සාකච්ඡා කිරීමෙන් (සාකච්ඡාය පඤ්ඤා වේදිතබ්බා)", "නිහඬව සිටීමෙන්", "ධනවත්කමෙන්", "ශාරීරික ශක්තියෙන්", "විමසා බලා කරන සාකච්ඡාවෙන් කෙනෙකුගේ නුවණ හඳුනාගත හැකිය."),
    q("සත්තජටිල සූත්‍රයට අනුව කෙනෙකුගේ වීර්යය හා ධෛර්යය පරීක්ෂා කළ හැක්කේ කවර අවස්ථාවකදීද?", "විපතක් පැමිණි අවස්ථාවකදී (ආපදාසු ථාමෝ වේදිතබ්බෝ)", "සැප විඳින විටදී", "උත්සව අවස්ථාවකදී", "නිදා සිටින විටදී", "දුෂ්කරතා හා අභියෝග හමුවේ මුහුණ දෙන ආකාරයෙන් ශක්තිය මැනිය හැකිය."),
    q("ලෝකයේ හටගැනීම හා අවසානය මේ බඹයක් පමණ වූ ශරීරය තුළම පනවන බව බුදුරදුන් දෙසූ සූත්‍රය කුමක්ද?", "රෝහිතස්ස සූත්‍රය", "ආනාපානසති සූත්‍රය", "මහාමංගල සූත්‍රය", "පරාභව සූත්‍රය", "දුක, දුකට හේතුව හා නිවන මිනිස් සිත හා කය ඇසුරෙන්ම අවබෝධ කළ යුතුය."),
    q("ධර්මය අසා ක්‍රියාත්මක නොවන්නා 'අන් අයගේ ගවයන් රකින ගොපල්ලෙකුට' උපමා කර ඇත්තේ කවර පිටක ග්‍රන්ථයේද?", "ධම්මපදයේ (යමක වග්ගයේ)", "විනය පිටකයේ", "අභිධර්ම පිටකයේ", "ජාතක පොතේ", "'ගෝපෝව ගාවෝ ගණයං පරේසං' ගාථාවෙන් පිළිවෙතේ වැදගත්කම පෙන්වයි."),
    q("බුදුරදුන්ගේ 'මහාසීහනාද සූත්‍රයේ' ප්‍රධාන වශයෙන් විස්තර කරන්නේ කුමක්ද?", "තථාගත දසබල ඥාන හා සතර විශාරද ඥාන", "සතර සංග්‍රහ වස්තු", "පංච ශීලය", "සංගායනා ඉතිහාසය", "සුනක්ඛත්ත ලිච්ඡවී පුත්‍රයාගේ චෝදනා බිඳ දමමින් බුදුරදුන්ගේ අසමසම ඥාන විස්තර කෙරේ."),
    q("ධම්මපදයේ 'ජරා වග්ගයට' අනුව 'පස්ස චිත්තකතං බිම්බං' යන්නෙන් අදහස් කරන්නේ කුමක්ද?", "විසිතුරු ලෙස සැරසූ ලෙඩ දුක්වලට ගොදුරු වන ශරීරය", "ලෝහ ප්‍රතිමාවක්", "මාලිගාවක බිතුසිතුවමක්", "දිව්‍ය රථයක්", "රෝගාබාධ හා ජරාවට පත්වන කයෙහි නිසරු ස්වභාවය මෙයින් පැහැදිලි වේ."),
    q("සූත්‍ර දේශනාවල එන 'චතුස්සච්ච ධම්ම' යන්නෙන් නිරන්තරයෙන්ම අවධාරණය කෙරෙන්නේ කුමක්ද?", "චතුරාර්ය සත්‍යය", "සතර සතිපට්ඨානය", "සතර බ්‍රහ්ම විහරණ", "සතර සංග්‍රහ වස්තු", "සියලු බුද්ධ දේශනාවල හරය චතුරාර්ය සත්‍යය වටා ගෙතී ඇත.")
  )
}
